def check_good_triple(x, y, z):
    # Check constraints for calculating P
    if x == 0 or y == 0 or z == 0:
        # If any base or exponent is zero, the expression might be ill-defined or zero/one, 
        # which cannot yield a prime.
        return None, None

    try:
        # Handle potential complex number issues if bases are negative and exponents are non-integers,
        # but here x, y, z are integers, so the result should be real.
        p = y**x * z**y * x**z
    except OverflowError:
        return None, None

    if p <= 0:
        return None, None

    if is_prime(int(p)):
        S = x**2 + y**2 + z**2
        return p, S
    return None, None

